rtEntry(CLK := bEntry);
IF rtEntry.Q THEN
  IF bLarge THEN nLarge := nLarge + 1;
  ELSE nSmall := nSmall + 1;
  END_IF
END_IF

CASE nState OF
  0: IF bStart THEN nState := 1; END_IF
  1: bMotor := TRUE;
     tonDiv(IN := rtLarge.Q, PT := T#2S);
     bDiverter := tonDiv.Q;
END_CASE

tonJam(IN := bEntry, PT := T#10S);
IF tonJam.Q THEN bFault := TRUE; END_IF
IF bReset AND NOT bEntry THEN bFault := FALSE; END_IF
bMotor := bRun AND NOT bFault;
